window.DADOS_ATUALIZACOES = [{"titulo":"Atualizações dos Sistemas","data":"2026-10-02","arquivo":"Atualizacoes_dos_Sistemas_02.10.2026.docx","sistemas":[{"nome":"API ProSind","versao":"","titulo":"API ProSind","itens":[{"texto":"Desenvolvida uma API para compartilhar informações para outros sistemas e ou plataformas de nossos clientes.\nCampos abaixo liberados para API:\n• Ativo (valor booleano, indicando se o beneficiário é um cadastro ativo ou não)\n• Nome Sócio\n• RG\n• CPF\n• Cadastro/Matrícula e dígito\n• Data Nascimento Sócio\n• Telefone Sócio\n• Endereço Sócio\n• Complemento\n• E-mail Sócio\n• Registro Profissional Sócio\n• Telefone Sócio\n• CEP Sócio\n• UF\n• Cidade\n• Bairro\n• CNPJ Empresa\n• Financeiro = S(Em Dia) ou N (Atraso) com a Mensalidade","chamados":[],"caminho":"","tipo":"Novidade"}]},{"nome":"APP Acessos ProSind","versao":"1.1.0","titulo":"APP Acessos ProSind 1.1.0","itens":[{"texto":"APP Acessos ProSind:\n• Configuração da Catraca ProSind\nArquivo - configurações - aba Entradas e Saídas Manuais\n\"_ Permitir Informar Número Convidados\",\n• APP Acessos ProSind:\nConforme configuração do item A), se marcado abrir exibirá checkBox “_Permitir informar nº de convidados”. Somente 2 dígitos inteiros.\nOBS: Deverá ser instalado e testado junto com Sistema ProSind Catraca 1.0.8.0.","chamados":["APPAC-7"],"caminho":"","tipo":"Alteração"}]},{"nome":"Acordos","versao":"1.0.69.2","titulo":"Sistema Acordos 1.0.69.2","itens":[{"texto":"Adicionado LOG no Sistema Acordos.","chamados":["SAP-73"],"caminho":"","tipo":"Novidade"},{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["SAP-74"],"caminho":"","tipo":"Alteração"},{"texto":"Cadastros > Não Sócios: Adicionado o campo DDI (Discagem Direta Internacional). Para poder enviar WhatsApp para Sócios/Não Sócios que estão em outros países.","chamados":["AGW-762"],"caminho":"Cadastros > Não Sócios","tipo":"Novidade"}]},{"nome":"Acordos WEB","versao":"1.0.1.5","titulo":"Sistema Acordos WEB 1.0.1.5","itens":[{"texto":"AcordosWeb: Desenvolvido LOG no sistema.","chamados":["SAPWEB-14"],"caminho":"","tipo":"Novidade"}]},{"nome":"AgendaW","versao":"3.4.50.5","titulo":"Sistema AgendaW 3.4.50.5","itens":[{"texto":"Cadastro - Ficha - Botão Imprimir - Ficha e Ficha Benefícios/Selecionar: Alterado para funcionar o campo DSIDENTIFICACAO ao imprimir a Ficha quando as opções abaixo estão Desmarcadas:\nArquivos > Configurações > Parâmetros > Ficha:\n_Imprimir Assinatura na Ficha e Ficha Benef./Convênio;\n_ Imprimir GER na Ficha e Ficha Benef./Convênio;","chamados":["AGW-775"],"caminho":"Cadastro - Ficha - Botão Imprimir - Ficha e Ficha Benefícios/Selecionar","tipo":"Alteração"},{"texto":"Cadastro – AgendaW - ABA Empresa/Escritório com CPF do funcionário: Atualizada funcionalidade de Bloquear o Sócios e Não Sócios, após fazer um agendamento, com o CNPJ alfanumérico.\nOBS: Aba Escritório: tem a configuração em Arquivo > Configurações > aba AgendaWeb > Aba > Geral: \"Digitar CNPJ da Empresa quando logado como Escritório\", é necessário estar marcada para que ao informar o CPF no agendamento do Funcionário.","chamados":["AGW-777"],"caminho":"Cadastro – AgendaW - ABA Empresa/Escritório com CPF do funcionário","tipo":"Alteração"},{"texto":"Cadastro - Agenda – Ficha: Adicionado na ficha a hora (HH:MM:SS) quando usuário Inclusão/Alteração.","chamados":["AGW-778"],"caminho":"Cadastro - Agenda – Ficha","tipo":"Novidade"},{"texto":"Relatórios - Agenda - Período/Assinatura: Adicionada na telinha \"Agenda do Período\" o checkBox \"_Assinatura de 1 linha\", se marcado adiciona uma linha com um traço abaixo do NOME/DEPENDENTE \"Ass:_______\" até o final da página.","chamados":["AGW-779"],"caminho":"Relatórios - Agenda - Período/Assinatura","tipo":"Novidade"}]},{"nome":"AgendaWEB","versao":"1.1.2.9","titulo":"Sistema AgendaWEB 1.1.2.9","itens":[{"texto":"AgendaWeb > Menu Horários Seguidos: Adicionado no AGW Desktop em Cadastros > Convênios > botão Horários > \"Definir Intervalos\".\nNecessário ter o horário definido para o convênio para depois selecionar esses horários como Intervalo. Então no AgendaWEB irá exibir na tabela:\n\"12:00 - INTERVALO\"\n\"12:30 - INTERVALO\"\nObs 1: Só exibirá \"INTERVALO\" na tabela se tiver apenas UM convênio com Horários gerados abertos.\nSe existir mais de UM convênio com Horários gerados abertos no mesmo dia, não exibirá na WEB na coluna Situação, a expressão \"INTERVALO\", porque o sistema consegue identificar sozinho quando tem mais de UM convênio com horários gerados em aberto, como era antes.\nObs 2: para o horário definido como \"Intervalo\", o sistema não permitirá marcar como \"horário normal\" e vice-versa. Para evitar de o horário estar marcado como Intervalo e horário normal ao mesmo tempo.\nNa AgendaWeb o sistema checará a tabela de Intervalos, se apenas tiver horários gerados em Aberto para apenas 1 convênio (rotina checada apenas para a opção \"Horários Seguidos\").","chamados":["AGWEB-143"],"caminho":"AgendaWeb > Menu Horários Seguidos","tipo":"Novidade"}]},{"nome":"Assembleia ProSind","versao":"1.0.75.2","titulo":"Sistema Assembleia ProSind 1.0.75.2","itens":[{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["SASSP-31"],"caminho":"","tipo":"Alteração"},{"texto":"Cadastros > Não Sócios: Adicionado o campo DDI (Discagem Direta Internacional). Para poder enviar WhatsApp para Sócios/Não Sócios que estão em outros países.","chamados":["AGW-762"],"caminho":"Cadastros > Não Sócios","tipo":"Novidade"}]},{"nome":"Atendimentos ProSind","versao":"1.0.1.1","titulo":"Sistema Atendimentos ProSind 1.0.1.1","itens":[{"texto":"O sistema de Atendimento ProSind, por senhas é uma solução inovadora para o controle de filas, que ao mesmo tempo em que permite selecionar o serviço desejado, já organiza a recepção da Entidade sem causar tumultos.\nIntegrado ao Sistema Painel, é possível fazer a chamar da senha impressa, através de uma tela ou painel e direcionar o sócio ou não sócios para o atendimento.\nSistema Atendimentos ProSind: Botão Configurações > Aba Parâmetros: Adicionado na parte inferior da tela o campo “Hash”. Esse Hash é obtido no Sistema Painel. Campo URL não precisa preencher.","chamados":["SAC-6"],"caminho":"","tipo":"Novidade"}]},{"nome":"Auxílio Doença","versao":"1.0.28.2","titulo":"Sistema Auxílio Doença 1.0.28.2","itens":[{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["AUXD-30"],"caminho":"","tipo":"Alteração"},{"texto":"Cadastros > Não Sócios: Adicionado o campo DDI (Discagem Direta Internacional). Para poder enviar WhatsApp para Sócios/Não Sócios que estão em outros países.","chamados":["AGW-762"],"caminho":"Cadastros > Não Sócios","tipo":"Novidade"}]},{"nome":"CaixaW ProSind","versao":"9.3.88.5","titulo":"Sistema CaixaW ProSind 9.3.88.5","itens":[{"texto":"Relatórios - Contas a Pagar - por Fornecedor/Anual: Otimizado o relatório para ficar mais rápido.","chamados":["CXW-515"],"caminho":"Relatórios - Contas a Pagar - por Fornecedor/Anual","tipo":"Alteração"}]},{"nome":"Cálculos ProSind","versao":"2.2.41.0","titulo":"Sistema Cálculos ProSind 2.2.41.0","itens":[{"texto":"Alterado o nome do tipo de afastamento, \"Pedido Demissão Com Justa Causa\" para \"Pedido de Rescisão Indireta\" em:\n- Cálculos - Cálculos - Prévia de Rescisão > campo Afastamento;\n- Cálculos > Homologações > campo Afastamento.","chamados":["CLW-215"],"caminho":"","tipo":"Alteração"}]},{"nome":"Catraca ProSind","versao":"1.0.9.8 a 1.0.9.9","titulo":"Sistema Catraca ProSind 1.0.9.8 a 1.0.9.9","itens":[{"texto":"Adicionado o Relatórios – “Histórico Dia/Empresa”.","chamados":["PSC-85"],"caminho":"","tipo":"Novidade"},{"texto":"Arquivo - Configuração – Aba Bloqueios > _Utilizar Indicador de Bloqueio do Cadastro de Sócios/Não Sócios: Adicionada funcionalidade para se esta opção marcada, consistir os Dependentes e não permitir que entrem na catraca se o sócio/não sócio está Bloqueado.","chamados":["PSC-93"],"caminho":"Arquivo - Configuração – Aba Bloqueios > _Utilizar Indicador de Bloqueio do Cadastro de Sócios/Não Sócios","tipo":"Novidade"},{"texto":"Adicionada funcionalidade para exibir aviso de perda de conexão com a rede/banco de dados. Agora exibirá tela \"Atenção: Erro de Rede. A conexão com o banco de dados foi perdida: Error reading data from the connection. Por favor tente logar novamente...\"","chamados":["PSC-94"],"caminho":"","tipo":"Novidade"}]},{"nome":"Colônia de Férias ProSind","versao":"1.6.11.2","titulo":"Sistema Colônia de Férias ProSind 1.6.11.2","itens":[{"texto":"Cadastro – Reserva: Adicionado na tela antes da Obs, o campo “Vaga Garagem”. Com a opção de “Cadastro de Vaga de Garagem”. Em Cadastro de Colônias é necessário ir em Listas > “Cadastrar Vaga de Garagem” e depois “Vincular Vagas de Garagem”.","chamados":["SCFP-481"],"caminho":"Cadastro – Reserva","tipo":"Novidade"},{"texto":"Cadastro Reserva – Pagamentos: Nas configurações > Dados Padrões > Pagamentos > \"_ Data de Pagamento Dia/Não Alterar\" está desmarcada, alterado para colocar a mesma data de pagamento na data de caixa, caso seja informada data de pagamento menos que o dia de hoje. Se opção marcada, ficará como está hoje.","chamados":["SCFP-482"],"caminho":"Cadastro Reserva – Pagamentos","tipo":"Alteração"},{"texto":"Relatórios - Reservas - Colônia/Com Sem Pagto: Adicionada nova opção \"Sem Pagamentos Maior Zero ou Parcial\". Listará as Reservas com saldo da guia maior que zero, ou seja, sem pagamento ou pagamento parcial. Obs: usam Reserva de Grupo e deixam o valor ZERO, e não querem que essas reservas apareçam no relatório, por isso foi feita essa nova opção \"Sem Pagamentos Maior Zero ou Parcial\".","chamados":["SCFP-483"],"caminho":"Relatórios - Reservas - Colônia/Com Sem Pagto","tipo":"Novidade"}]},{"nome":"ColôniaWEB ProSind","versao":"1.0.0.9","titulo":"Sistema ColôniaWEB ProSind 1.0.0.9","itens":[{"texto":"Adicionada funcionalidade para enviar e-mail com QRCODE de chave PIX, para o e-mail do sócio/não sócio que fez a pré-reserva na ColoniaWEB. Configurado no Sistema Colônia Desktop em Cadastro - Colônia - Botão Configurar - opção \"Pré-Reseva > Documento Configurável - E-mail\". OBS: O QRCODE deve ser gerado no APP do Banco.","chamados":["CSWEB-8"],"caminho":"","tipo":"Novidade"}]},{"nome":"ConsultaSócio","versao":"1.0.0.7","titulo":"Sistema ConsultaSócio 1.0.0.7","itens":[{"texto":"Sistema usado em conveniadas ou farmácias para consultar o limite Valor Limite e Saldo do sócio.\nAdicionada Criptografia para Senha e caminho banco dados. Adicionado ao entrar com usuário em Configuração - ABA Banco dados - Botão Reconfigurar.","chamados":["AGW-511"],"caminho":"","tipo":"Novidade"}]},{"nome":"ConsultaSócioWEB ProSind","versao":"1.0.1.3","titulo":"Sistema ConsultaSócioWEB ProSind 1.0.1.3","itens":[{"texto":"Consulta SóciosWeb – menu Consulta Sócio: Adicionada funcionalidade para pesquisar pela Matrícula também. Na lista da pesquisa, adicionada à coluna “Bloqueio”.","chamados":["CSWEB-13"],"caminho":"Consulta SóciosWeb – menu Consulta Sócio","tipo":"Novidade"}]},{"nome":"ConsultaWEB ProSind","versao":"1.0.1.4 a 1.0.2.0","titulo":"Sistema ConsultaWEB ProSind 1.0.1.4 a 1.0.2.0","itens":[{"texto":"ConsultaWEB: Adicionada a funcionalidade responsiva no sistema.","chamados":["SCW-17"],"caminho":"","tipo":"Novidade"},{"texto":"ConsultaWeb - Menu Consulta Sócio:\nA) Adicionado nos Níveis de permissões:\n- Processos Jurídicos -> Sócios ou Não sócios\nB) Consulta Sócio: Após a pesquisa do sócio/não sócios e selecionado exibirá os dados do cadastro e no final do \"Listar\" foi adicionado \"Processos Jurídicos\" em uma nova coluna.\nC) Ao clicar na opção \" Processos Jurídicos\" o sistema exibirá todos os processos deste sócio/não. Exibirá também se houver, Data Audiência e hora.\nD) Adicionada opção para clicar nas “Fases” do processo.","chamados":["SCW-19"],"caminho":"ConsultaWeb - Menu Consulta Sócio","tipo":"Novidade"},{"texto":"ConsultaWeb - Menu Consulta Sócio – Pesquisar por: Adicionado o filtro \"CNPJ da Empresa”. Após filtrar a empresa, adicionado na exibição da lista, a coluna Situação (Sócio, Desfiliado, Aposentado ou Afastado).","chamados":["SCW-20"],"caminho":"ConsultaWeb - Menu Consulta Sócio – Pesquisar por","tipo":"Novidade"},{"texto":"ConsultaWeb - Menu Consulta Empresa:\n• Adicionado nos Níveis de permissões:\n- Processos Jurídicos -> Empresa\n• Consulta Sócio: Após a pesquisa do sócio/não sócios e selecionado exibirá os dados do cadastro e no final do \"Listar\" foi adicionado \"Processos Jurídicos\" em uma nova coluna.\n• Ao clicar na opção \"Processos Jurídicos\" o sistema exibirá todos os processos deste sócio/não. Exibirá também se houver, Data Audiência e hora.\n• Adicionada opção para clicar nas “Fases” do processo.","chamados":["SCW-21"],"caminho":"ConsultaWeb - Menu Consulta Empresa","tipo":"Novidade"},{"texto":"ConsultaWeb - Niveis Permissão: Alterada rotina de níveis de permissão para ficar mais rápido quando existem mais de 20 usuários.","chamados":["SCW-22"],"caminho":"ConsultaWeb - Niveis Permissão","tipo":"Alteração"},{"texto":"ConsultaWeb - Menu Consulta Empresa: Na Consulta da Empresa no botão Consulta \"Processos Jurídicos\" o sistema lista os processos da reclamante (no caso da empresa). Alterado para listar também os processos da RECLAMADA, buscando pelo nome da empresa e ou nome abreviado da empresa.","chamados":["SCW-23"],"caminho":"ConsultaWeb - Menu Consulta Empresa","tipo":"Alteração"},{"texto":"ConsultaWeb - Menu Consulta Empresa: No menu, Consulta da Empresa, no botão Consulta \"Processos Jurídicos\" o sistema lista os processos da reclamante e Reclamada (no caso da empresa). Alterado para listar também os processos da RECLAMADA do sócio e não sócio.","chamados":["SCW-24"],"caminho":"ConsultaWeb - Menu Consulta Empresa","tipo":"Alteração"}]},{"nome":"Controle de Veículos e Multas ProSind","versao":"1.0.20.3","titulo":"Sistema Controle de Veículos e Multas ProSind 1.0.20.3","itens":[{"texto":"O Sistema Controle de Veículos e Multas ProSind, possibilita o cadastro de Veículos, Multas e Pontuação dos condutores, para auxiliar a entidade a controlar as informações do associado que deseja recorrer a uma multa de trânsito.\nCadastro - Multas - Botão Contatos: Alterado para permitir alterar o Não Sócio para Sócio quando Não Sócio possui Contatos. Cadastros de Multas > Contatos > Listas > Coluna Observações: Alterado para exibir acentuação corretamente.","chamados":["SCVMP-35"],"caminho":"","tipo":"Alteração"},{"texto":"Cadastros > Não Sócios: Adicionado o campo DDI (Discagem Direta Internacional). Para poder enviar WhatsApp para Sócios/Não Sócios que estão em outros países.","chamados":["AGW-762"],"caminho":"Cadastros > Não Sócios","tipo":"Novidade"}]},{"nome":"Convenção ProSindWeb","versao":"1.0.0.2","titulo":"Sistema Convenção ProSindWeb 1.0.0.2","itens":[{"texto":"Sistema Convenção ProSindWeb com configuração para marcar os tipos de Contribuições e quantidades vencidas para empresas e escritórios poderem acessar esta área do ProSindWeb no menu ‘Convenções Coletivas” para baixar/visualizar as convenções coletivas de trabalho.\nNo Painel Administrativos dos Módulos: Adicionado ao nosso painel de configurações a opção de máscara da vigência.","chamados":["SCPSWEB-9"],"caminho":"","tipo":"Novidade"}]},{"nome":"ConvênioWEB ProSind","versao":"1.1.0.3","titulo":"Sistema ConvênioWEB ProSind 1.1.0.3","itens":[{"texto":"Adicionada funcionalidade para exibir \"Situação + Nome Sócio + (Inscrição)\" quando no sistema ProSind está marcada a opção \"_ Não Permitir Sócios Com Local de Pagamento SINDICATO-SEDE\", para no login \"Conveniada\", for localizar o Sócio(sócio, afastado ou aposentado). OBS: Com esta forma de exibição a conveniada não lançará no sistema convênio do sindicato, mas poderá dar um desconto nas compras deste convênio, pois o sócios pagará direto ao conveniada.","chamados":["CVWEB-79"],"caminho":"","tipo":"Novidade"}]},{"nome":"Creche ProSind","versao":"2.0.14.1","titulo":"Sistema Creche ProSind 2.0.14.1","itens":[{"texto":"Sistema de gerenciamento de creche com controle de crianças/dependentes dos sócios da entidade visando fornecer segurança para o associado e o dependente/criança. Gerenciamento dos cadastros das crianças/dependentes com as referidas turmas da creche, cadastrando os familiares (fone, parentesco e quem pode retirar a criança da creche) e o controle financeiro das mensalidades da creche.\nObjetivo - Fornecer segurança e controle das crianças/dependentes que são deixados pelo associado na creche.\nVersionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["CRE-46"],"caminho":"","tipo":"Alteração"}]},{"nome":"Currículos ProSind","versao":"1.0.68.2","titulo":"Sistema Currículos ProSind 1.0.68.2","itens":[{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["CUR-50"],"caminho":"","tipo":"Alteração"},{"texto":"Cadastros > Não Sócios: Adicionado o campo DDI (Discagem Direta Internacional). Para poder enviar WhatsApp para Sócios/Não Sócios que estão em outros países.","chamados":["AGW-762"],"caminho":"Cadastros > Não Sócios","tipo":"Novidade"}]},{"nome":"Cursos e Eventos ProSind","versao":"1.0.15.0","titulo":"Sistema Cursos e Eventos ProSind 1.0.15.0","itens":[{"texto":"Sistema de gerenciamento de Cursos e Eventos, aplicados pelas entidades para controlar as presenças, médias, emissão de contrato e certificados através de um documento configurável, a cobrança será feita pelo sistema ProSindW em lançamentos descontos com local de pagamento sindicato-sede (através de boletos), Debito Bancário, Empresa-Folha. No Cadastro de Matrículas, existe um botão “Lançamentos” para lançar os valores para os matriculados.\nCadastro - Matrículas - Aba Não Sócios - Botão Não Sócios: Adicionado o Campo DDI (Discagem Direta Internacional).","chamados":["SCEP-26"],"caminho":"","tipo":"Novidade"}]},{"nome":"CursosWEB ProSind","versao":"1.0.0.2","titulo":"Sistema CursosWEB ProSind 1.0.0.2","itens":[{"texto":"Sistema de gerenciamento de Cursos e Eventos Web, para o Professor poder fazer o registro/controle de presença do aluno e registrar as notas. Aluno pode visualizar as suas notas, presenças do curso em que está matriculado e se inscrever em novos cursos disponíveis.\nAdicionada funcionalidade para enviar documentos para cada curso. O envio de arquivos pode ser feito pelo login Professor.","chamados":["SCEP-4-B"],"caminho":"","tipo":"Novidade"}]},{"nome":"E-mail ProSind","versao":"1.0.21.0","titulo":"Sistema E-mail ProSind 1.0.21.0","itens":[{"texto":"Adicionado LOG em todo o sistema.","chamados":["SEM-14"],"caminho":"","tipo":"Novidade"},{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["SEM-15"],"caminho":"","tipo":"Alteração"}]},{"nome":"Estoque ProSind","versao":"1.0.70.0","titulo":"Sistema Estoque ProSind 1.0.70.0","itens":[{"texto":"Cadastro - Requisições: Adicionado na tela à opção Assinatura, para usar o coletor (Step Over).","chamados":["ESW-78"],"caminho":"Cadastro - Requisições","tipo":"Novidade"}]},{"nome":"FiliaWeb ProSind","versao":"1.0.2.7 a 1.0.2.9","titulo":"Sistema FiliaWeb ProSind 1.0.2.7 a 1.0.2.9","itens":[{"texto":"Sistema FiliaWeb: Adicionado LOG no PSW apenas quando o cadastro for Aprovado no FiliaWEB na tabela LOG_REGISTRO.","chamados":["FWEB-16"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: Adicionado funcionalidade de consulta CEP no formulário de cadastro.","chamados":["FWEB-32"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: Adicionado no Painel de Configurações do Número do cliente > aba Configurações > Atualização de cadastros > Campos:\n- \"Checkbox Atualização Obrigatório\" = Sim/Não. Obs: Necessário que o ComboBox “Permitir Alterar Cadastros” esteja diferente de “Não”.\n- Campo \"Checkbox Atualização Texto\": Para digitar o Texto do CheckBox. Por exemplo: Li e aceito os termos acima.\n- Campo \"Texto Cabeçalho\": Para digitar um texto especial para quando um sócio se logar no sistema. Por exemplo: Ficha de Atualização Cadastral da Filiação.\n- Campo “Texto”: Para digitar uma informação de várias linhas antes do “CheckBox Atualização Texto”. Por exemplo: Declaro que as informações fornecidas neste formulário são verdadeiras e me responsabilizo por sua exatidão. Estou ciente de que informações incorretas ou falsas podem acarretar penalidades legais.\"","chamados":["FWEB-34"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: No Painel da Direta > selecionar o cliente > aba Configurações > Outras Configurações > Adicionado o ComboBox “CPF Dep Obrigatório=Sim/Não”.\nPara tornar ou não obrigatório o preenchimento do “CPF do Dependente” no preenchimento de um novo cadastro","chamados":["FWEB-35"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: No Painel da Direta > Selecionar o cliente > Aba Campos > Adicionados os campos:\na) Nome Social\nb) Etnia (cor).\nObs: Necessário configurar as colunas: Status, Obrigatório, Ordem, Espaço para ser exibido no formulário de cadastro.\nc) Adicionada funcionalidade para localizar o endereço ao digitar o CEP + TAB ou Enter.","chamados":["FWEB-37"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: No painel do cliente foi adicionada a coluna Matrícula com opção de ordenar por Matrícula, se clicar no título da coluna. Obs: Para exibir esta coluna, precisa está Habilitado e Obrigatório nas configurações dos clientes: na aba Campos.","chamados":["FWEB-38"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: No formulário de Cadastro/Atualização: Adicionada funcionalidade para permitir apenas letras, números, vírgulas, pontos ou hífens em: Endereço, Complemento, Bairro.","chamados":["FWEB-39"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: No Painel da Direta > Selecionar o cliente > Aba Dados > Adicionado antes do botão \"Salvar\" o ComboBox \"Status = Ativo/Inativo\".","chamados":["FWEB-40"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: No Painel da Direta > selecionar o cliente > aba Configurações > Outras Configurações > Adicionado o ComboBox “Dt Nasc Dep Obrigatório=Sim/Não”. Para tornar ou não obrigatório o preenchimento da Data de Nascimento do Dependente, no preenchimento de um novo cadastro.","chamados":["FWEB-41"],"caminho":"","tipo":"Novidade"},{"texto":"Sistema FiliaWeb: Adicionado campo de e-mail de resposta nas configurações.","chamados":["FWEB-42"],"caminho":"","tipo":"Novidade"}]},{"nome":"Homologador ProSind","versao":"1.0.3.5 a 1.0.3.6","titulo":"Sistema Homologador ProSind 1.0.3.5 a 1.0.3.6","itens":[{"texto":"- No Login Funcionário do Sindicato: Configurações > E-mail: Adicionado o novo “Formato Situação Especial”, e nos outros Formatos foi adicionado um botão \"Padrão\" na parte superior direita ao lado do Título do e-mail.\n- Para usar esta nova opção, no Login Funcionário do Sindicato, ao entrar em uma homologação APROVADA, no canto superior direito, botão “Mais opções” > foi adicionado “Adicionado Aviso de Situação”, ao selecionar o Aviso Especial, e salvar irá enviar um e-mail com esse aviso especial conforme configuração.\n- O Aviso Especial pode ser cadastrado em:\n- No Login Funcionário do Sindicato: Em Cadastros > Situações Extras > Listas Situações Extras ou Nova Situação Extra. Na Nova Situação Extra, pode-se cadastrar um aviso de Situação Especial e configurar as opções abaixo:\n• Enviar Notificação das Situações Especiais: Sim/Não;\n• Permitir Visualização pela Empresa/Trabalhador: Sim/Não.","chamados":["SHW-85"],"caminho":"","tipo":"Novidade"},{"texto":"Alterado a Descrição do Tipo de Afastamento: \"Pedido Demissão Com Justa Causa\" para \"Pedido de Rescisão Indireta\".","chamados":["SHW-86"],"caminho":"","tipo":"Alteração"},{"texto":"Adicionado campo do DDI no cadastro da homologação e também na tela do trabalhador caso ele queira modificar seus dados de contato.","chamados":["SHW-87"],"caminho":"","tipo":"Novidade"},{"texto":"Login funcionário Sindicato: canto superior direito > Alterar meus dados > Aba Assinatura > Alterar Assinatura > ícone de lápis (Digitar assinatura) > Permitindo digitar a Assinatura.","chamados":["SHW-88"],"caminho":"","tipo":"Alteração"},{"texto":"Adicionada funcionalidade, para não permitir Finalizar uma nova Homologação se o campo \"Data de Homologação\" superior ao dia atual.","chamados":["SHW-89"],"caminho":"","tipo":"Novidade"},{"texto":"Homologador - Envio de Notificação Automática por E-mail para Homologações com Situação Revisão: Adicionada funcionalidade de envio automático de lembretes para as rescisões que permanecem com a situação \"Revisão\" conforme o e-mail e contato telefônico com o cliente. Para configurar ir no Menu > Configurações > Gerais > Enviar lembrete automático para homologação em “Revisão” a cada quantos dias ?\nMelhorias no cadastro da homologação, incluindo navegação por Enter/Shift+Enter e indicação dos campos inválidos. Reformulação do histórico da homologação, modais, tabelas, filtros e comportamento responsivo.\nMelhorias na abertura, visualização e download de arquivos. Ajustes de permissões para consulta e visualização de arquivos. Melhorias no menu, no cabeçalho, rodapé, indicadores de conexão e experiência em dispositivos móveis.","chamados":["SHW-90"],"caminho":"Homologador - Envio de Notificação Automática por E-mail para Homologações com Situação Revisão","tipo":"Novidade"},{"texto":"Adicionadas as opções de template para Retorno-Entidade e Retorno, que podes ser configurados no Menu > Configurações > E-mail > Templates de E-mail > Retorno e Retorno-Entidade, para criar um aviso específico por e-mail se a Homologação é Nova ou Retorno da Revisão.","chamados":["SHW-91"],"caminho":"","tipo":"Novidade"},{"texto":"Adicionada nova situação \"Retorno\": Homologações reenviadas após revisão aparecem como nova situação \"Retorno\" nas telas e nos e-mails.","chamados":["SHW-92"],"caminho":"","tipo":"Novidade"},{"texto":"Na parte onde ficam os arquivo anexados, adicionados botões \"Aprovar\", \"Invalidar\", \"Cancelar Aprovação\" para cada documento. Para identificar qual já foi verificado, e qual ainda precisa ser verificado ou corrigido.","chamados":["SHW-93"],"caminho":"","tipo":"Correção"}]},{"nome":"Jurídico ProSind","versao":"1.1.15.1","titulo":"Sistema Jurídico ProSind 1.1.15.1","itens":[{"texto":"Cadastro – Atendimentos: Atualizada rotina para quando um Não Sócio tem atendimento no Jurídico e no Sistema ProSindW e tento passar ele de Não Sócio para Sócio.","chamados":["JUR-171"],"caminho":"Cadastro – Atendimentos","tipo":"Alteração"},{"texto":"Cadastro - Atendimentos - botão Documentos: Atualizada rotina para quando um Não Sócio tem atendimento com imagens no botão Documentos no Jurídico e no Sistema ProSindW e tento passar ele de Não Sócio para Sócio.","chamados":["JUR-172"],"caminho":"Cadastro - Atendimentos - botão Documentos","tipo":"Alteração"},{"texto":"Adicionado opção para permitir ou não a nova opção em: Utilitários > Usuários/Permissões > Opções > Movimentos > Importação > \"SetoresWeb Visita/Fiscalização\".\nAdicionado em Movimentos - Importação – “SetoresWeb Visita/Fiscalização”.\nCadastros > Processos > Botão \"Fases\": Adicionado botão \"Documentos\".","chamados":["JUR-173"],"caminho":"","tipo":"Novidade"},{"texto":"Atualizadas funcionalidades para o Campo CNPJ Alfanumérico, em:\n• Cadastros - Processos - Localizar - Campo CNPJ Alfanumérico;\n• Cadastros - Processos - Reclamante e Reclamada - Cliente - Opções de Filtro - campo – CNPJ;\n• Cadastros - Processos - Reclamada - Nome Vinculado - Opções de Filtro - campo – CNPJ;\n• Cadastros - Atendimentos - Aba Empresas - Inscrição (clique aqui para selecionar) - Opções de Filtro - campo - CNPJ;\n• Cadastros - Agenda Compromissos - Responsável (ADV) (clique aqui para selecionar) - Opções de Filtro - campo –\nCNPJ;\n• Cadastros - Advogados - Localiza - Opções de Filtro - campo – CNPJ.","chamados":["JUR-174"],"caminho":"","tipo":"Alteração"}]},{"nome":"JurídicoWeb","versao":"1.0.0.9","titulo":"Sistema JurídicoWeb 1.0.0.9","itens":[{"texto":"Alterada URL criada no Admin para ser todo em letra minúscula.","chamados":["JWEB-4"],"caminho":"","tipo":"Novidade"},{"texto":"Adicionado no INI do JurídicoWEB, nas configurações, a opção:\n\"_Exibir Menu Atendimentos” com opção de exibir todas as Situações (Aberto/Andamento/Fechado) ou alguma(s).\nOBS: O usuário apenas visualiza os atendimentos e os andamentos, não permite alterar ou interagir com os atendimentos ou andamentos.","chamados":["JWEB-6"],"caminho":"","tipo":"Novidade"}]},{"nome":"Locadora ProSind","versao":"1.0.23.2","titulo":"Sistema Locadora ProSind 1.0.23.2","itens":[{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["SLP-17"],"caminho":"","tipo":"Alteração"},{"texto":"Cadastros > Não Sócios: Adicionado o campo DDI (Discagem Direta Internacional). Para poder enviar WhatsApp para Sócios/Não Sócios que estão em outros países.","chamados":["AGW-762"],"caminho":"Cadastros > Não Sócios","tipo":"Novidade"}]},{"nome":"Mensagens ProSind","versao":"1.0.12.1","titulo":"Sistema Mensagens ProSind 1.0.12.1","itens":[{"texto":"O Sistema Mensagens ProSind, possibilita o cadastro de usuários/funcionários, envio de mensagens entre os funcionários da entidade e cadastrar lembretes. O sistema também possibilita receber notificações das empresas que se cadastraram através do Sistema ProSindWEB.\nAdicionado Log para Upgrade.\nAdicionado LOGs de Entrada, alteração de senha.\nAlterado para que usuário Inativo não logue no sistema.","chamados":["MEN-7"],"caminho":"","tipo":"Novidade"},{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["MEN-8"],"caminho":"","tipo":"Alteração"}]},{"nome":"Ouvidoria ProSind","versao":"1.0.22.0","titulo":"Sistema Ouvidoria ProSind 1.0.22.0","itens":[{"texto":"O Sistema Ouvidoria ProSind possibilita o cadastro de atendimentos e/ou gerenciar as denúncias, reclamações, sugestões e elogios para a Entidade Sindical.\nVersionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["OUV-41"],"caminho":"","tipo":"Alteração"}]},{"nome":"Ouvidoria WEB ProSind","versao":"1.0.1.0","titulo":"Sistema Ouvidoria WEB ProSind 1.0.1.0","itens":[{"texto":"O Sistema OuvidoriaWebProSind, possibilita o cadastro dos atendimentos e/ou consulta dos protocolos de atendimento. O sistema estará rodando no site do cliente (internet) com o banco de dados no servidor do cliente.\nAtravés de um usuário e senha a categoria poderá consultar e/ou fazer denúncias, reclamações, sugestões e elogios para a Entidade Sindical.\nOuvidoriaWeb : Desenvolvido o sistema no layout Responsivo, para se adaptar automaticamente a diferentes tamanhos de tela e dispositivos, como desktops, tablets e smartphones.","chamados":["OUW-7"],"caminho":"","tipo":"Novidade"}]},{"nome":"Painel ProSind","versao":"3.0.0.0 a 3.0.0.2","titulo":"Sistema Painel ProSind 3.0.0.0 a 3.0.0.2","itens":[{"texto":"O Sistema Painel ProSind fornece um gerenciamento de chamadas de atendimento personalizadas num painel exposto pelo Cliente. Funciona integrado com o Sistema AgendaW ProSind organizando as chamadas agendadas para atendimento, exibindo em uma tela (TV ou vídeo), de escolha do cliente, uma Mensagem, nome do sócio ou dependente a ser atendido, o Guichê e o atendente, inclusive com um som para a chamada de atendimento.\nObjetivo -Fornecer uma solução personalizada de chamadas de atendimento, com maior comodidade.\nSistema Painel: Desenvolvido novo sistema Painel dentro dos Módulos da Direta Sistemas:\n* Adicionado um cadastro de Informativos que pode ter os tipos:\n- Texto;\n- Imagem;\n- Vídeo (upload)\n- Link Youtube\n* Adicionado um cadastro de Painéis com opções de configurações individuais para cada um, opções para configurar:\n- Logomarca Cliente\n- Detalhes da chamada atual\n- Detalhes da Última chamada\n* Adicionado um Dashboard:\n- Exibe a Quantidade de Painéis e a quantidade de Informativos configurados;\n- Exibe a Quantidade de Chamadas Recebidas;\nObs: Para configurar mais Painéis no sistema AgendaW, é necessário ir no sistema AgendaW em Cadastros > Painel: e preencher no \"Computador 1\"\n- Setor: 1\n- Mesa: 1\n- Hash: AAAbbb\nno \"Computador 2\":\n- Setor: 2\n- Mesa: 2\n- Hash: AAAbbb => hash é por cliente, não muda.\nObs 2: Adicionada funcionalidade para o Sistema Atendimentos ProSind também.","chamados":["PAI-18"],"caminho":"","tipo":"Novidade"}]},{"nome":"Plano de Saúde ProSind","versao":"1.1.13.1 a 1.1.13.4","titulo":"Sistema Plano de Saúde ProSind 1.1.13.1 a 1.1.13.4","itens":[{"texto":"Adicionado em Movimentos - Conferência – “Plano Saúde SULMED”: com opção para selecionar a Conveniada e o tipo Plano.","chamados":["PLW-166"],"caminho":"","tipo":"Novidade"},{"texto":"Movimentos - Conferência - Plano Saúde Hapvida: Adicionada funcionalidade para selecionar mais de uma conveniada.","chamados":["PLW-167"],"caminho":"Movimentos - Conferência - Plano Saúde Hapvida","tipo":"Novidade"},{"texto":"Movimentos - Importação de Dados - Empresa - Inclusão/Alteração/Exclusão: Adicionadas funcionalidades para as opções que podem vir no arquivo CSV referente à coluna B = A (Alteração) ou E (Exclusão) e Coluna R=10:\nAlteração: O Não Sócio esta com Tipo Plano = 2, ao importar um Tipo Plano = 1, adicionadas funcionalidades para finalizar (incluir o fim da adesão) os planos (conveniadas) que estavam vigentes e incluir o novo Tipo Plano conforme dados da planilha e da tela de importação.\nOBS: Necessário informar data de Fim Adesão menor que hoje, pois não pode incluir um Convênio + Tipo Plano que ainda não finalizou.\nExclusão: Na importação da planilha de exclusão, adicionadas funcionalidades para Gravar o “Fim de adesão” em todas as conveniadas informadas na tela e na conveniada que vem informada na planilha (Coluna R), conforme as regras da coluna C.","chamados":["PLW-168"],"caminho":"Movimentos - Importação de Dados - Empresa - Inclusão/Alteração/Exclusão","tipo":"Novidade"}]},{"nome":"ProFederação ProSind","versao":"2.1.20.1","titulo":"Sistema ProFederação ProSind 2.1.20.1","itens":[{"texto":"Cadastros > Entidades Sindicais > campo CNPJ: Adicionada funcionalidade para aceitar letras no CNPJ. Movimentos > Arquivo Contribuições > Importação Contribuições Entidades: Adicionada funcionalidade para aceitar importação de CNPJ’s com letras.","chamados":["PFW-260"],"caminho":"Cadastros > Entidades Sindicais > campo CNPJ","tipo":"Novidade"}]},{"nome":"ProFederação Web","versao":"1.0.2.1 a 1.0.2.2","titulo":"Sistema ProFederação Web 1.0.2.1 a 1.0.2.2","itens":[{"texto":"ProFederacaoWeb: Adicionada funcionalidade para aceitar letras no Login CNPJ da Entidade.","chamados":["PFWEB-18"],"caminho":"","tipo":"Novidade"}]},{"nome":"ProSind Backup","versao":"5.0.0.3","titulo":"Sistema ProSind Backup 5.0.0.3","itens":[{"texto":"Alterada a lógica de compactação e descompactação de arquivos.","chamados":["PSBK-10"],"caminho":"","tipo":"Alteração"},{"texto":"Otimização do sistema de Backup.","chamados":[],"caminho":"","tipo":"Alteração"}]},{"nome":"ProSind Backup Cloud","versao":"1.0.0.0","titulo":"Sistema ProSind Backup Cloud 1.0.0.0","itens":[{"texto":"Sistema para fazer backup do Banco de Dados do Sistema ProSind na nuvem.","chamados":[],"caminho":"","tipo":"Alteração"}]},{"nome":"ProSindMail","versao":"1.3.79.1 a 1.3.79.4","titulo":"Sistema ProSindMail 1.3.79.1 à 1.3.79.4","itens":[{"texto":"ProSindMail - Mala Direta - Por WhatsApp: Adicionada funcionalidade para gravar as mensagens enviadas via WhatsApp no botão Contatos das referidas tabelas. Para isso é necessário configurar em Arquivo > configurações > Aba Parâmetros > Registrar Contatos > nas opções de WhatsApp nas Abas: Sistema ProSind, Sistema ProFederação e Sistema CaixaW. Adicionada funcionalidade para gravar os Contatos da Tabela \"Dirigentes do PROFER\" e Tabela \"Cad DIVERSOS PROFER\".","chamados":["PSMAIL-346"],"caminho":"ProSindMail - Mala Direta - Por WhatsApp","tipo":"Novidade"},{"texto":"ProSindMail - Mala Direta - Por WhatsApp - Enviar WhatsApp Oficial: Adicionada funcionalidade para no “Campo Sugerido/Digitar”, poder digitar o sinal de Ordinal com \"Alt+167\".","chamados":["PSMAIL-347"],"caminho":"ProSindMail - Mala Direta - Por WhatsApp - Enviar WhatsApp Oficial","tipo":"Novidade"},{"texto":"ProSindMail - Mala Direta - Por E-mail: Alterado para que os Boletos feitos no ProSindW, acate a configuração no PSMAIL de \"_ Inserir Assinatura\" do cadastro de contas de e-mail automaticamente\".","chamados":["PSMAIL-348"],"caminho":"ProSindMail - Mala Direta - Por E-mail","tipo":"Alteração"}]},{"nome":"ProSindW","versao":"3.6.57.0 a 3.6.57.17","titulo":"Sistema ProSindW 3.6.57.0 à 3.6.57.17","itens":[{"texto":"Arquivo > Configurações > Parâmetros > Parâmetros : Adicionada a opção “Contrato PIX Automático:___”. Informar um contrato Lytex com as chaves do contrato com a Lytex.\nUtilitários > Tabelas de Sistema > Entidade: Adicionado o campo “Chave Direta” (Este campo de ser gerado pela Direta).\nUtilitários > Tabelas de Sistema > ProSindWeb/API: Adicionado campos URL Api Direta. No Upgrade este campo será preenchido.\nCom os parâmetros informados, será exibido o botão \"Pagamento com Pix\" ao lado da \"Data de Vencimento\" nos menus:\n• Cadastros > Contribuições Empresas > Contribuições Empresas > Pagamentos Empresas;\n• Cadastros > Contribuições Sócios/Não Sócios > Contribuições > Pagamentos Sócios e Não Sócios.\nAo clicar no botão \"Pagamento com Pix\", exibirá o navegador padrão com o QRCode para pagamento, e o Sistema ficará aguardando o pagamento por 5 minutos. Se ultrapassar os 5 minutos, exibirá “tempo expirado”, será necessário clicar no botão \"Pagamento com Pix\" novamente.","chamados":["PSW-4756"],"caminho":"Arquivo > Configurações > Parâmetros > Parâmetros","tipo":"Novidade"},{"texto":"Movimentos - Arquivos Contribuições - Baixar Retornos Web Services - SICOOB-756: Adicionada funcionalidade para baixar os retornos por WebService no SICOOB-756.","chamados":["PSW-4806"],"caminho":"Movimentos - Arquivos Contribuições - Baixar Retornos Web Services - SICOOB-756","tipo":"Novidade"},{"texto":"Movimentos - Lançamentos Desconto Folha - Importação de Dados - Layout CPF Titular Dependente: Adicionada na tela a opção de \"_ Não Consistir CPF Dependentes\".\nOBS: No layout no campo do CPF do dependente do arquivo verifica qual é o sócio ou não sócio deste dependente. Se esta opção nova está marcada não checa mais o CPF do dependente do sócio ou não sócio, apenas verifica se este CPF é de um sócio ou não sócio. Se não existir criticará. Os dependentes não vão mais ter convênio. Serão cadastrados como Não Sócio se o dependente quiser.","chamados":["PSW-4808"],"caminho":"Movimentos - Lançamentos Desconto Folha - Importação de Dados - Layout CPF Titular Dependente","tipo":"Novidade"},{"texto":"Relatórios - Contribuições Empresas - Contribuições Atraso - Atrasos - Empresa e Situação: Adicionado o campo E-MAIL, O campo FAX separado por / ao lado do campo Fone, e o campo Não Sócios (Digitado).","chamados":["PSW-4809"],"caminho":"Relatórios - Contribuições Empresas - Contribuições Atraso - Atrasos - Empresa e Situação","tipo":"Novidade"},{"texto":"Relatórios - Relatório Mágico – na tabela DEPENDENTE SÓCIOS e DEPENDENTES NÃO SÓCIOS, no passo 2) Selecione os Campos: Adicionado os campos:\n- Data de nascimento do sócio/não sócio;\n- Celular do sócio/não sócio: Adicionados os campos.","chamados":["PSW-4811"],"caminho":"Relatórios - Relatório Mágico – na tabela DEPENDENTE SÓCIOS e DEPENDENTES NÃO SÓCIOS, no passo 2) Selecione os Campos","tipo":"Novidade"},{"texto":"Adicionado em Movimentos - Arquivo Contribuições - Importação Contribuições Empresas – “Layout Cobrança 4”.","chamados":["PSW-4813"],"caminho":"","tipo":"Novidade"},{"texto":"Adicionado em Movimentos - Sócios e Não Sócios - Exportação Dados – “Sócios e Dependentes Telemedicina”.","chamados":["PSW-4814"],"caminho":"","tipo":"Novidade"},{"texto":"Relatórios - Lançamentos Descontos - Creditados - Lançamentos Creditados/Conveniada/Forma Pagamento: Adicionado no relatório os lançamentos de desconto que estão vinculados a uma contribuição de grupo de contribuições de sócios/não sócios (quando o LDE estiver vinculado (campo CDGRUPO)).","chamados":["PSW-4819"],"caminho":"Relatórios - Lançamentos Descontos - Creditados - Lançamentos Creditados/Conveniada/Forma Pagamento","tipo":"Novidade"},{"texto":"Adicionado em Movimentos - Lançamentos Desconto Folha - Importação de Dados – “Layout Curitiba FAT129 Co-Participação”.","chamados":["PSW-4823"],"caminho":"","tipo":"Novidade"},{"texto":"Movimentos - Oposições das Contribuições - Exportação – Documentos: Adicionado na tela \"_ Exportar pela Empresa da Época\" => Exportará os documentos anexados da oposição do sócio/não sócio de acordo com a empresa informada na tela. Se marcar o checkBox, exportará os documentos das oposições dos sócios/não sócios de acordo com a empresa da época. Exportar para Pasta: Diretório padrão configurado em \"Arquivo - configurações - diversos - diretórios - arquivos de exportação\".","chamados":["PSW-4824"],"caminho":"Movimentos - Oposições das Contribuições - Exportação – Documentos","tipo":"Novidade"},{"texto":"Adicionada a Coluna Código (grupo da empresa), após o nome abreviado e a Situação da Empresa em:\n- Cadastro - Empresas - Listas - CNPJ Raiz/Grupo:\n- Cadastro - Empresas - Listas - Empresas CCT;\nCadastro - Empresas - Listas - Empresas Classificação: Adicionada a Listas - “Empresas Classificação” com as mesmas colunas da Listas - Empresas CCT.","chamados":["PSW-4825"],"caminho":"","tipo":"Novidade"},{"texto":"Adicionado em Cadastro - Empresas - Listas - \"Empresas Filiais\".","chamados":["PSW-4826"],"caminho":"","tipo":"Novidade"},{"texto":"Relatórios - Contribuições Empresas - Contribuições Pagas - Pagas - Por Cidade: Adicionado na última página do relatório um \"TOTAL GERAL: 99 de Cidades\" - TOTAL GERAL DE QTDE PAGAMENTOS, TOTAL GERAL DE EMPREGADOS, TOTAL GERAL DE VALOR.","chamados":["PSW-4828"],"caminho":"Relatórios - Contribuições Empresas - Contribuições Pagas - Pagas - Por Cidade","tipo":"Novidade"},{"texto":"Relatórios - Relatório Mágico - Tabela Sócios/Não Sócios - Filtro ASSINATURA: adicionado o campo \"ASSINATURA DIGITAL\" para filtrar no passo 3)Filtrando.","chamados":["PSW-4829"],"caminho":"Relatórios - Relatório Mágico - Tabela Sócios/Não Sócios - Filtro ASSINATURA","tipo":"Novidade"},{"texto":"Adicionado em Relatórios - Cipa – “Por Local Trabalho”.","chamados":["PSW-4830"],"caminho":"","tipo":"Novidade"},{"texto":"Adicionado em Cadastro - Empresas – Listas – “Relação Processos/Fases Reclamada”. Requer ultimo upgrade do Sistema Jurídico \"JUR_1.1.15.0.exe\".","chamados":["PSW-4832"],"caminho":"","tipo":"Novidade"},{"texto":"Lytex: Ajustado a alteração de Valor, Vencimento de Pedido de Baixa dos Boletos da Lytex sem passar Scopes da Requisição.","chamados":["PSW-4835"],"caminho":"","tipo":"Correção"},{"texto":"Adicionada à nova opção \"Contribuições x Oposições x Autorizações\" em:\n- Cadastro - Contribuições Empresas - Contribuições Empresas - Pagamento Empresas - Listas - \"Contribuições x Oposições x Autorizações\";\n- Cadastro - Empresa - Imprimir - Listas - \"Contribuições x Oposições x Autorizações\";\n- Cadastro - Empresa - Listas - \"Contribuições x Oposições x Autorizações\".\nOBS: Para exibir a Oposição/Autorização no GRID é necessário ter o Tipo de Contribuição gerada.","chamados":["PSW-4836"],"caminho":"","tipo":"Novidade"},{"texto":"Adicionado em Relatórios > Estatísticas > Previsão Arrecadação Boletos > “Contribuições/Anuidades/Mensalidades/Lançamento Desconto/Filtro”. Será informado na tela o Vencimento Inicial, a partir desta data será contado 16 dias para frente e mostrado em colunas.","chamados":["PSW-4837"],"caminho":"","tipo":"Novidade"},{"texto":"Cadastro - Oposições das Contribuições e Cadastro Autorizações das Contribuições: Adicionado como chave primária o código da empresa (cdempresa), não muda nada nestas telas, aceitando apenas uma contribuição por sócio/contribuição/mês/ano. OBS: Para entidades que possuem sócios e não sócios que trabalham em 2 empresas e o Sistema RegistraWeb vai registrar o sócio e sua respectiva empresa informada no RegistraWeb.","chamados":["PSW-4838"],"caminho":"Cadastro - Oposições das Contribuições e Cadastro Autorizações das Contribuições","tipo":"Novidade"},{"texto":"Utilitários - Sorteios - Botão Excluir do Grid: Alterado para exibir o botão Excluir dos prêmios sorteados.","chamados":["PSW-4839"],"caminho":"Utilitários - Sorteios - Botão Excluir do Grid","tipo":"Alteração"},{"texto":"Movimentos - Lançamentos Desconto Folha - Exportação de Dados - Arquivo de Lançamentos Descontos - Layout Servidores 7: Alterada tela de seleção \"Conveniadas\" para \"Benefícios das Conveniadas\".","chamados":["PSW-4842"],"caminho":"Movimentos - Lançamentos Desconto Folha - Exportação de Dados - Arquivo de Lançamentos Descontos - Layout Servidores 7","tipo":"Alteração"}]},{"nome":"ProSindWeb","versao":"1.3.1.9 a 1.3.2.1","titulo":"Sistema ProSindWeb 1.3.1.9 à 1.3.2.1","itens":[{"texto":"No Sistema PSWEB, item 2.3.4 - Relatório Lançamentos dos Convênios - Total por Sócio: Adicionado CheckBox \"_CPF\", se marcado exibe coluna CPF formatada no relatório.","chamados":["PSWEB-379"],"caminho":"No Sistema PSWEB, item 2.3.4 - Relatório Lançamentos dos Convênios - Total por Sócio","tipo":"Novidade"},{"texto":"Adicionadas no INI as opções:\n\"__\" 6.23 Permitir Botão Cálculo Boletos de Anuidade de Sócios Baixados/Vencidos (PSW 3.6.5.7+) => Se somente esta opção marcada, irá calcular Juros e Multa a partir da Data de vencimento do boleto.\n\"_____\" 6.24 Quantidade máxima de dias para Cálculo, usando o vencimento original da Anuidade do Sócio => Se nesta opção for informada quantidade a de dias por exemplo, 90 dias, exibirá o botão \"Calcular\", irá calcular o Juros/Multa do Anuidade a partir da data de vencimento do boleto de anuidade. Para Anuidades de 2026 (com vencimento 31/01/2026 + 90 dias = 01/05/2026 será a data limite para cálculo) Se a data de hoje for maior que 01/05/2026, não permitirá fazer o cálculo.","chamados":["PSWEB-381"],"caminho":"","tipo":"Novidade"}]},{"nome":"ProSind Cloud","versao":"","titulo":"Sistema ProSind Cloud","itens":[{"texto":"ProSind Cloud: Menu Arrecadações > Arrecadação Individual > Empresa > Alterado para localizar CNPJ com máscara.","chamados":["PSCLOUD-66"],"caminho":"","tipo":"Alteração"}]},{"nome":"ProSind Gerencial","versao":"1.0.0.1","titulo":"Sistema ProSind Gerencial 1.0.0.1","itens":[{"texto":"O Sistema Gerencial apresenta vários gráficos para melhorar a tomada de decisão da entidade.","chamados":[],"caminho":"","tipo":"Alteração"}]},{"nome":"Protocolo ProSind","versao":"1.0.26.0","titulo":"Sistema Protocolo ProSind 1.0.26.0","itens":[{"texto":"Cadastro - Protocolo - Botão Andamentos: Alterado para exibir as telas de \"Relação de Órgão/Setor\" ao dar \"0 + Enter\" ou a descrição se informar o código.","chamados":["PRW-41"],"caminho":"Cadastro - Protocolo - Botão Andamentos","tipo":"Alteração"},{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["PRW-42"],"caminho":"","tipo":"Alteração"}]},{"nome":"Registra WEB ProSind","versao":"1.0.1.2 a 1.0.1.4","titulo":"Sistema Registra WEB ProSind 1.0.1.2 a 1.0.1.4","itens":[{"texto":"Sistema para registrar as Autorizações e Oposições dos Sócios e Não Sócios.\nRegistraWEB: Adicionada funcionalidade para gravar o IP que confirmou o registro da Carta de Oposição, essa informação será gravada nas oposições do PSW quando tiver o campo.","chamados":["RWEB-50"],"caminho":"","tipo":"Novidade"},{"texto":"Quando uma Oposição ou Autorização for excluída no Sistema ProSindW, e no sistema RegistraWEB com Login do usuário da entidade, no menu Oposições ou Autorizações > Entrar na contribuição (ícone Lápis), se tiver alguma Oposição ou Autorização excluída (no PSW), exibirá uma aba “Lista de Exclusão (2)” com um contador ao lado da aba “Dados”.\nOBS: No Painel do cliente precisa estar configurado o campo “Lista de Exclusão = SIM”.","chamados":["RWEB-51"],"caminho":"","tipo":"Alteração"},{"texto":"RegistraWeb - Empresa Selecionada: No painel do cliente, no menu Configurações, campo Empresa, adicionado “x” para remover a empresa padrão.","chamados":["RWEB-52"],"caminho":"RegistraWeb - Empresa Selecionada","tipo":"Novidade"},{"texto":"No painel dos Clientes em Módulos da Direta, na tela de configuração do RegistraWeb: Adicionado os campos abaixo para informar a mensagem personalizada com até 100 posições:\n- Mensagem Login Não Encontrado;\n- Mensagem se CNPJ Não Encontrado no Cadastro.","chamados":["RWEB-53"],"caminho":"","tipo":"Novidade"},{"texto":"RegistraWeb - Logo Login:\na) Alteração na busca do Logo do Login;\nb) Ajustada à visualização do Link no qual direciona para o Link do Opositor;\nc) Link Sessão.","chamados":["RWEB-54"],"caminho":"RegistraWeb - Logo Login","tipo":"Correção"},{"texto":"RegistraWeb - No Registro da Oposição Controle de Sessão: Adicionada funcionalidade de um temporizador de sessão no painel do opositor, renova a sessão com a navegação.","chamados":["RWEB-55"],"caminho":"RegistraWeb - No Registro da Oposição Controle de Sessão","tipo":"Novidade"}]},{"nome":"ReportProSind","versao":"1.0.3.0","titulo":"Sistema ReportProSind 1.0.3.0","itens":[{"texto":"Aumentado o limite suportado de tamanho de arquivo “.FRP”, gerados pelos sistemas ProSind, para 1.9 GB.","chamados":["PSW-1378"],"caminho":"","tipo":"Alteração"}]},{"nome":"Requisições ProSind","versao":"1.0.59.1","titulo":"Sistema Requisições ProSind 1.0.59.1","itens":[{"texto":"Cadastros - Conveniadas - Campo Conta Bancária: Aumentado o tamanho do campo Conta Bancária.","chamados":["SRE-121"],"caminho":"Cadastros - Conveniadas - Campo Conta Bancária","tipo":"Alteração"}]},{"nome":"Requisições WEB ProSind","versao":"1.0.2.9","titulo":"Sistema Requisições WEB ProSind 1.0.2.9","itens":[{"texto":"Adicionado LOG em todo o sistema.","chamados":["SREW-28"],"caminho":"","tipo":"Novidade"}]},{"nome":"Setores ProSind","versao":"1.0.18.0","titulo":"Sistema Setores ProSind 1.0.18.0","itens":[{"texto":"Versionamento para o Módulo Atualizador de Sistemas da Direta.","chamados":["SET-21"],"caminho":"","tipo":"Alteração"}]},{"nome":"Setores WEB ProSind","versao":"1.0.5.2","titulo":"Sistema Setores WEB ProSind 1.0.5.2","itens":[{"texto":"SetoresWeb:\n- No Menu Setores > Botão Localizar > na relação dos Setores, na última coluna clicar em “Agendar” > Exibirá a tela “Agendar Visita por Setor” e no final exibirá todas as Empresas do setor, alterado para vir default todos os CheckBox já selecionados;\n- na tela \"Agendar Visita por Setor\": Adicionado antes da tabela com a Lista de Empresas, a informação: * Selecione as empresas. Para marcar/desmarcar todas, clique no CheckBox ao lado de Empresa;\n- No Menu Setores > Informar Empresa, botão Localizar > na lista exibida clicar na penúltima coluna “Empresas” > na lista das Empresas, clicar na penúltima coluna “Agenda” > Na tela de “Agendar Visitas”, informar a Data, Hora, Tipo Visita, Situação e Gravar > Quando for Editar essa visita, exibirá o botão “Registrar Visita” > Na tela de Registro de Visita terá o campo “Próximo Estágio” e quando for alterada para “Finalizada” foi adicionado para exibir um POP-UP: “Atenção! Deseja registrar pendências/ocorrências? SIM ou NÃO” > Após clicar no SIM exibirá a tela de Registro de Ocorrências;\n- Adicionado o novo menu “Pendências”, com o quantitativo das Situações Pendente e Aguardando Resposta;\n- No menu “Visita Agendada” > clicar no botão Localizar > Exibirá Setores/Empresas > Na última coluna Opções, adicionada a opção “Registrar”, que exibirá a tela “Registro de Visita” para registrar a visita. OBS: A opção Editar: vai exibir a tela de \"Agendar Visita\";\n- No menu “Visita Agendada” > botão Localizar > exibiu a “Agenda Visitas” por Setor/Empresa > Se algum dos registros listados tiver pendências a resolver, irá exibir em azul BIC “Possui 999 Pendências”, Ao clicar exibirá um pop-up com código ocorrência, Data, Situação, Assessor, para fechar a telinha clicar no X ou no ESC.\n- Tela Registro de Visita: Removido o CheckBox “_Pendências” da tela que ficava ao lado do Próximo Estágio;\n- Tela Registro de Visita: Alterada para exibir corretamente no modo Mobile;.","chamados":["SWEB-68"],"caminho":"","tipo":"Novidade"}]}],"id":"2026-10-02"}];
